                 '.product-card {\n'
                 '  display: flex; flex-direction: column; padding: 1rem;\n'
                 '  border: 1px solid var(--border); border-radius: 12px; transition: all 0.2s;\n'
                 '}\n'
                 '.product-image { width: 100%; aspect-ratio: 4 / 3; }\n'
                 '.product-info { display: grid; grid-template-columns: 1fr; gap: 0.5rem; }\n'
