                 'if config.config_file_name is not None:\n'
                 '    fileConfig(config.config_file_name)\n'
                 '\n'
                 'target_metadata: MetaData = Base.metadata\n'
                 'target_metadata.naming_convention = NAMING_CONVENTION  # 关键：约束自动命名\n'
                 '\n'
                 'def run_migrations_offline() -> None:\n'
                 '    url = config.get_main_option("sqlalchemy.url")\n'
                 '    context.configure(\n'
                 '        url=url, target_metadata=target_metadata, literal_binds=True,\n'
                 '        dialect_opts={"paramstyle": "named"},\n'
                 '        render_as_batch=True,  # SQLite 等支持批处理ALTER\n'
                 '        compare_type=True, compare_server_default=True,\n'
                 '        include_object=include_object_fn\n'
                 '    )\n'
                 '    with context.begin_transaction():\n'
                 '        context.run_migrations()\n'
                 '\n'
                 'def include_object_fn(object, name, type_, reflected, compare_to):\n'
