                 '            compare_server_default=True,\n'
                 '            include_object=include_object_fn,\n'
                 '            transaction_per_migration=True,  # 每个迁移独立事务\n'
                 '            lock_timeout=30                   # DDL 锁超时 30s\n'
                 '        )\n'
                 '        with context.begin_transaction():\n'
                 '            context.run_migrations()\n'
                 '\n'
                 'if context.is_offline_mode():\n'
                 '    run_migrations_offline()\n'
                 'else:\n'
                 '    run_migrations_online()\n'
                 '\n'
                 '# ====== app/db/naming.py — 约束命名公约防分支冲突 ======\n'
                 'NAMING_CONVENTION = {\n'
                 '    "ix": "ix_%(column_0_label)s",\n'
                 '    "uq": "uq_%(table_name)s_%(column_0_N_name)s",\n'
                 '    "ck": "ck_%(table_name)s_%(constraint_name)s",\n'
                 '    "fk": "fk_%(table_name)s_%(column_0_N_name)s_%(referred_table_name)s",\n'
                 '    "pk": "pk_%(table_name)s",\n'
                 '}\n'
                 '\n'
                 '# ====== 典型迁移 revision 示例：data-only 迁移 ======\n'
                 "'''${message}\n"
                 '\n'
                 'Revision ID: 0004_add_user_status\n'
                 'Revises: 0003_user_baseline\n'
                 'Create Date: 2024-06-15 11:22:33\n'
                 '\n'
                 "'''\n"
                 'from alembic import op\n'
                 'import sqlalchemy as sa\n'
                 'from sqlalchemy import update\n'
                 'from sqlalchemy.orm import Session\n'
                 '\n'
                 '# revision identifiers, used by Alembic.\n'
                 "revision = '0004_add_user_status'\n"
                 "down_revision = '0003_user_baseline'\n"
                 'branch_labels = None\n'
                 'depends_on = None\n'
                 '\n'
                 'def upgrade() -> None:\n'
                 "    op.add_column('users', sa.Column('status', sa.String(16), nullable=False,\n"
                 "                  server_default='ACTIVE'))\n"
                 "    op.create_index('ix_users_status_created', 'users', ['status', 'created_at'])\n"
                 '    bind = op.get_bind(); sess = Session(bind)\n'
                 '    from app.models import User\n'
                 "    sess.execute(update(User).where(User.email.endswith('@test.com')).\n"
                 "                 values(status='INACTIVE'))\n"
                 '    sess.commit()\n'
                 '\n'
                 'def downgrade() -> None:\n'
                 "    op.drop_index('ix_users_status_created', 'users')\n"
                 "    op.drop_column('users', 'status')\n"
                 '\n'
                 '# ====== 多分支 HEAD 合并：建一个 merge migration ======\n'
                 '# 场景: Alice 分支 head=0005_add_posts, Bob 分支 head=0006_add_tags\n'
